create table public.organizations(id uuid primary key default gen_random_uuid(), name text not null, kind text, size text, website text, status text not null default 'pending', verified_at timestamptz, subscription_status text not null default 'inactive', created_at timestamptz not null default now());
create table public.organization_members(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, user_id uuid not null references auth.users on delete cascade, member_role text not null default 'member', unique(organization_id,user_id));
create table public.jobs(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations on delete cascade, title text not null, description text not null default '', mode text, location text, status text not null default 'draft', required_skills jsonb not null default '[]', created_at timestamptz not null default now());
create table public.candidate_profiles(student_id uuid primary key references public.students on delete cascade, discoverable boolean not null default false, alias_data jsonb not null default '{}', skills jsonb not null default '[]', study_stage text, uni_category text, scrubbed_summary text, embedding extensions.vector(768), refreshed_at timestamptz not null default now());
create index candidate_profiles_embedding_hnsw on public.candidate_profiles using hnsw (embedding extensions.vector_cosine_ops);
create table public.match_results(id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs on delete cascade, student_id uuid not null references public.students on delete cascade, alias text not null, final_score numeric not null, confidence numeric not null, reasons text[] not null default '{}', gaps text[] not null default '{}', created_at timestamptz not null default now(), unique(job_id,student_id));
create table public.demand_signals(id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs on delete cascade, university_id uuid references public.universities, reason_counts jsonb not null default '{}', skill_slugs text[] not null default '{}', created_at timestamptz not null default now());
create table public.access_requests(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations, student_id uuid not null references public.students, job_id uuid not null references public.jobs, match_result_id uuid references public.match_results, message text, requested_scope text[] not null, granted_scope text[] not null default '{}', duration_days int, status text not null default 'pending' check(status in ('pending','accepted','declined','withdrawn','expired')), expires_at timestamptz, pipeline_stage text check(pipeline_stage in ('interviewing','offered','closed')), created_at timestamptz not null default now(), responded_at timestamptz);
create unique index access_request_active_uq on public.access_requests(organization_id,student_id,job_id) where status in ('pending','accepted');
create table public.feedback_options(option_code text primary key, label text not null);
create table public.feedback(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations, student_id uuid not null references public.students, request_id uuid not null references public.access_requests, option_codes text[] not null default '{}', note text check(length(note)<=280), created_at timestamptz not null default now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['organizations','organization_members','jobs','candidate_profiles','match_results','demand_signals','access_requests','feedback_options','feedback'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
create or replace function private.my_org_ids() returns uuid[] language sql stable security definer set search_path = '' as $$
 select coalesce(array_agg(m.organization_id),'{}'::uuid[]) from public.organization_members m where m.user_id=auth.uid()
$$;
create or replace function private.has_active_grant(p_org_id uuid,p_student_id uuid,p_scope text) returns boolean language sql stable security definer set search_path = '' as $$
 select exists(select 1 from public.access_requests r where r.organization_id=p_org_id and r.student_id=p_student_id and r.status='accepted' and r.expires_at>now() and p_scope=any(r.granted_scope))
$$;
revoke all on function private.my_org_ids(),private.has_active_grant(uuid,uuid,text) from public,anon;
grant execute on function private.my_org_ids(),private.has_active_grant(uuid,uuid,text) to authenticated;
